#!/usr/bin/env node
/**
 * Generate synthetic stub models for tests ONLY. These are not project
 * models: a Flatten + Dense network with zero weights and a fixed bias, so
 * its output is fully determined by the bias. The stubs exist to exercise
 * the detector pipeline (gate, queue, results, exports) without the real
 * converted models. Never ship them, never measure accuracy with them.
 *
 * Output (gitignored, regenerated by `npm run pretest:e2e`):
 *   tests/fixtures/stub-valid/stage1|stage2/{model.json,weights.bin,manifest.json}
 *   tests/fixtures/stub-invalid/stage1|stage2/{model.json,weights.bin,manifest.json}
 * stub-valid: Stage 1 top label is "0 ..." (gate passes), Stage 2 top is DWV.
 * stub-invalid: Stage 1 top label is "1 ..." (gate blocks Stage 2).
 *
 * The sets are also copied into apps/web/dist/{models,models-invalid} so the
 * preview server serves them as real files. Route interception is NOT used:
 * the detector loads its models inside a Web Worker, and the registered
 * service worker handles same-origin requests, so intercepted routes never
 * reach the worker's fetches. The build must run before the tests
 * (`npm run build`, then `npm run test:e2e`); rebuilding wipes dist, so do
 * not rebuild between the copy and the test run. Nothing here is shipped:
 * dist/ is gitignored and the stubs never enter the repository.
 */
import { cpSync, existsSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)));

const STAGE1_LABELS = ["0 Honey Bee or Beehive", "1 Not Honey Bee or Not Beehive"];
const STAGE2_LABELS = [
  "0 Healthy Honey Bee or Healthy Beehive",
  "1 Deformed Wing Virus (DWV)",
  "2 Varroa Mite Infestation",
  "3 Chalkbrood Disease",
];

function modelJson(units) {
  return {
    modelTopology: {
      class_name: "Sequential",
      config: {
        name: "sequential",
        layers: [
          {
            class_name: "InputLayer",
            config: {
              batch_input_shape: [null, 224, 224, 3],
              dtype: "float32",
              sparse: false,
              ragged: false,
              name: "input",
            },
          },
          {
            class_name: "Flatten",
            config: {
              name: "flatten",
              trainable: true,
              dtype: "float32",
              data_format: "channels_last",
            },
          },
          {
            class_name: "Dense",
            config: {
              name: "dense",
              trainable: true,
              dtype: "float32",
              units,
              activation: "softmax",
              use_bias: true,
              kernel_initializer: { class_name: "GlorotUniform", config: { seed: null } },
              bias_initializer: { class_name: "Zeros", config: {} },
              kernel_regularizer: null,
              bias_regularizer: null,
              activity_regularizer: null,
              kernel_constraint: null,
              bias_constraint: null,
            },
          },
        ],
      },
      keras_version: "2.12.0",
      backend: "tensorflow",
    },
    weightsManifest: [
      {
        paths: ["weights.bin"],
        weights: [
          { name: "dense/kernel", shape: [150528, units], dtype: "float32" },
          { name: "dense/bias", shape: [units], dtype: "float32" },
        ],
      },
    ],
  };
}

function weightsBin(units, bias) {
  const kernelCount = 150528 * units;
  const buffer = Buffer.alloc((kernelCount + units) * 4); // zeros: kernel + bias
  for (let i = 0; i < units; i += 1) {
    buffer.writeFloatLE(bias[i], (kernelCount + i) * 4);
  }
  return buffer;
}

function manifest(stage, labels) {
  return {
    convertedFrom: "stub (synthetic test fixture, not a project model)",
    inputRange: [-1, 1],
    inputSize: 224,
    labels,
    note: "TEST FIXTURE ONLY. Never ship or measure with this file.",
    parityReport: null,
    sourceSha256: "stub",
    stage,
    validPrefix: "0",
    version: "0.0.0-stub",
  };
}

function writeStage(dir, stage, labels, bias) {
  const units = labels.length;
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, "model.json"), JSON.stringify(modelJson(units)));
  writeFileSync(join(dir, "weights.bin"), weightsBin(units, bias));
  writeFileSync(join(dir, "manifest.json"), JSON.stringify(manifest(stage, labels), null, 2));
}

function writeSet(name, stage1Bias) {
  const base = join(root, name);
  writeStage(join(base, "stage1"), 1, STAGE1_LABELS, stage1Bias);
  writeStage(join(base, "stage2"), 2, STAGE2_LABELS, [0, 3, 0, 0]);
  console.log(`Wrote stub set: ${name}`);
}

writeSet("stub-valid", [3, 0]);
writeSet("stub-invalid", [0, 3]);

// Serve the stubs as real files from the preview server's dist folder.
const distDir = join(root, "..", "..", "apps", "web", "dist");
if (!existsSync(distDir)) {
  console.error("apps/web/dist not found. Run `npm run build` before `npm run test:e2e`.");
  process.exit(1);
}
cpSync(join(root, "stub-valid"), join(distDir, "models"), { recursive: true });
cpSync(join(root, "stub-invalid"), join(distDir, "models-invalid"), { recursive: true });
console.log("Copied stub sets into apps/web/dist/{models,models-invalid} (test runtime only, never shipped).");
